"""Group chat with speaker selection -- AutoGen GroupChat in miniature.

Three agents (coder, reviewer, manager), two selector variants
(round-robin, LLM-simulated), TERMINATE-token stop condition.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Callable, Optional


@dataclass
class Msg:
    speaker: str
    content: str


@dataclass
class Agent:
    name: str
    role: str
    policy: Callable[[list[Msg]], str]


def coder_policy(pool: list[Msg]) -> str:
    recent = [m for m in pool[-3:] if m.speaker != "coder"]
    last = recent[-1].content if recent else ""
    if "review" in last.lower() or "fix" in last.lower():
        return "revised code: return a + b"
    if not any(m.speaker == "coder" for m in pool):
        return "initial code: return a - b  (buggy)"
    return "TERMINATE"


def reviewer_policy(pool: list[Msg]) -> str:
    last_coder = next((m for m in reversed(pool) if m.speaker == "coder"), None)
    if last_coder is None:
        return "waiting for code"
    if "a - b" in last_coder.content:
        return "review: bug detected -- sum must be a+b, please fix"
    if "a + b" in last_coder.content:
        return "review: approved"
    return "review: unclear"


def manager_policy(pool: list[Msg]) -> str:
    approvals = [m for m in pool if m.speaker == "reviewer" and "approved" in m.content]
    if approvals:
        return "TERMINATE"
    return "manager: continue working"


AGENTS: dict[str, Agent] = {
    "coder": Agent("coder", "writes code", coder_policy),
    "reviewer": Agent("reviewer", "reviews code", reviewer_policy),
    "manager": Agent("manager", "keeps things moving", manager_policy),
}


def round_robin_selector(pool: list[Msg], team: dict[str, Agent]) -> Optional[str]:
    names = list(team.keys())
    if not pool:
        return names[0]
    idx = (names.index(pool[-1].speaker) + 1) % len(names)
    return names[idx]


def llm_style_selector(pool: list[Msg], team: dict[str, Agent]) -> Optional[str]:
    """Simulated LLM selector: picks based on recent context keywords.
    A real implementation is an LLM call with the recent pool."""
    if not pool:
        return "manager"
    last = pool[-1]
    if last.speaker == "coder":
        return "reviewer"
    if last.speaker == "reviewer":
        if "approved" in last.content:
            return "manager"
        return "coder"
    if last.speaker == "manager":
        return "coder"
    return None


def run_groupchat(
    team: dict[str, Agent],
    selector: Callable[[list[Msg], dict[str, Agent]], Optional[str]],
    max_rounds: int,
    label: str,
) -> list[Msg]:
    print(f"\n=== {label} ===")
    pool: list[Msg] = []
    trace: list[str] = []
    for _ in range(max_rounds):
        nxt = selector(pool, team)
        if nxt is None:
            break
        trace.append(nxt)
        agent = team[nxt]
        content = agent.policy(pool)
        pool.append(Msg(speaker=nxt, content=content))
        print(f"  [{nxt:8s}]: {content}")
        if content.strip().endswith("TERMINATE"):
            break
    print(f"  Selector trace: {trace}")
    print(f"  Rounds used: {len(pool)}")
    return pool


def speaker_counts(pool: list[Msg]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for m in pool:
        counts[m.speaker] = counts.get(m.speaker, 0) + 1
    return counts


def main() -> None:
    print("Group chat with speaker selection -- AutoGen GroupChat shape")
    print("-" * 62)

    p_rr = run_groupchat(AGENTS, round_robin_selector, max_rounds=8, label="Round-robin")
    print(f"  Speaker counts: {speaker_counts(p_rr)}")

    p_llm = run_groupchat(AGENTS, llm_style_selector, max_rounds=8, label="LLM-style (context-aware)")
    print(f"  Speaker counts: {speaker_counts(p_llm)}")

    print("\nObservations:")
    print("  - Round-robin gives every agent an equal turn regardless of context.")
    print("  - LLM-style routes by context; reviewer only speaks after coder, etc.")
    print("  - Both terminate on TERMINATE token or max_rounds.")


if __name__ == "__main__":
    main()

// Lesson: Group Chat and Speaker Selection (phase 16 / lesson 10)
// TypeScript port of code/main.py. Node standard library only.
// Source: phases/16-multi-agent-and-swarms/10-group-chat-speaker-selection/docs/en.md
// Run: npx tsx phases/16-multi-agent-and-swarms/10-group-chat-speaker-selection/code/main.ts

export {};

interface Msg {
  speaker: string;
  content: string;
}

interface Agent {
  name: string;
  role: string;
  policy: (pool: Msg[]) => string;
}

function coderPolicy(pool: Msg[]): string {
  const recent = pool.slice(-3).filter((m) => m.speaker !== "coder");
  const last = recent.length > 0 ? recent[recent.length - 1].content : "";
  if (last.toLowerCase().includes("review") || last.toLowerCase().includes("fix")) {
    return "revised code: return a + b";
  }
  if (!pool.some((m) => m.speaker === "coder")) {
    return "initial code: return a - b  (buggy)";
  }
  return "TERMINATE";
}

function reviewerPolicy(pool: Msg[]): string {
  const lastCoder = [...pool].reverse().find((m) => m.speaker === "coder");
  if (lastCoder === undefined) return "waiting for code";
  if (lastCoder.content.includes("a - b")) return "review: bug detected -- sum must be a+b, please fix";
  if (lastCoder.content.includes("a + b")) return "review: approved";
  return "review: unclear";
}

function managerPolicy(pool: Msg[]): string {
  const approvals = pool.filter((m) => m.speaker === "reviewer" && m.content.includes("approved"));
  if (approvals.length > 0) return "TERMINATE";
  return "manager: continue working";
}

type Team = Map<string, Agent>;

const AGENTS: Team = new Map([
  ["coder", { name: "coder", role: "writes code", policy: coderPolicy }],
  ["reviewer", { name: "reviewer", role: "reviews code", policy: reviewerPolicy }],
  ["manager", { name: "manager", role: "keeps things moving", policy: managerPolicy }],
]);

type Selector = (pool: Msg[], team: Team) => string | null;

function roundRobinSelector(pool: Msg[], team: Team): string | null {
  const names = [...team.keys()];
  if (pool.length === 0) return names[0];
  const idx = (names.indexOf(pool[pool.length - 1].speaker) + 1) % names.length;
  return names[idx];
}

function llmStyleSelector(pool: Msg[], team: Team): string | null {
  void team;
  if (pool.length === 0) return "manager";
  const last = pool[pool.length - 1];
  if (last.speaker === "coder") return "reviewer";
  if (last.speaker === "reviewer") {
    if (last.content.includes("approved")) return "manager";
    return "coder";
  }
  if (last.speaker === "manager") return "coder";
  return null;
}

function pyStrList(items: string[]): string {
  return "[" + items.map((s) => `'${s}'`).join(", ") + "]";
}

function runGroupchat(team: Team, selector: Selector, maxRounds: number, label: string): Msg[] {
  console.log(`\n=== ${label} ===`);
  const pool: Msg[] = [];
  const trace: string[] = [];
  for (let i = 0; i < maxRounds; i++) {
    const nxt = selector(pool, team);
    if (nxt === null) break;
    trace.push(nxt);
    const agent = team.get(nxt)!;
    const content = agent.policy(pool);
    pool.push({ speaker: nxt, content });
    console.log(`  [${nxt.padEnd(8)}]: ${content}`);
    if (content.trim().endsWith("TERMINATE")) break;
  }
  console.log(`  Selector trace: ${pyStrList(trace)}`);
  console.log(`  Rounds used: ${pool.length}`);
  return pool;
}

function speakerCounts(pool: Msg[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const m of pool) counts.set(m.speaker, (counts.get(m.speaker) ?? 0) + 1);
  return counts;
}

function pyCounts(c: Map<string, number>): string {
  return "{" + [...c.entries()].map(([k, v]) => `'${k}': ${v}`).join(", ") + "}";
}

function main(): void {
  console.log("Group chat with speaker selection -- AutoGen GroupChat shape");
  console.log("-".repeat(62));

  const pRr = runGroupchat(AGENTS, roundRobinSelector, 8, "Round-robin");
  console.log(`  Speaker counts: ${pyCounts(speakerCounts(pRr))}`);

  const pLlm = runGroupchat(AGENTS, llmStyleSelector, 8, "LLM-style (context-aware)");
  console.log(`  Speaker counts: ${pyCounts(speakerCounts(pLlm))}`);

  console.log("\nObservations:");
  console.log("  - Round-robin gives every agent an equal turn regardless of context.");
  console.log("  - LLM-style routes by context; reviewer only speaks after coder, etc.");
  console.log("  - Both terminate on TERMINATE token or max_rounds.");
}

main();
